/**
 * Speed and visual checks as a signed-in account, really executed: a local app with a login (a member, and an admin who also
 * needs an authenticator code), a signed-in dashboard that is slow on the server, signed-in pages that redirect visitors to
 * /login, an unstable signed-in page and public pages. Specs are generated by the real planner (a visitor-only browser), run by
 * the worker in real Chromium, and the generated script is also run under plain Playwright with environment variables.
 */
import { spawn } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import http from "node:http";
import { createRequire } from "node:module";
import os from "node:os";
import path from "node:path";
import type { Browser } from "playwright";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { loadConfig } from "../src/config.js";
import type { EngineContext } from "../src/engine/context.js";
import { launchChromium } from "../src/engine/discovery/browser.js";
import type { Reach } from "../src/engine/identity/access.js";
import { defaultAccount, loginFormFrom, needsSignIn, planSignedIn, roleAccount, signedInBudgets, signedInPageSteps, signInFailure, signInSteps, type LoginForm, type SignedInPlan } from "../src/engine/identity/signed-in.js";
import { generateSignedInPerformanceSpecs, generatePerformanceSpecs } from "../src/engine/performance/specs.js";
import { generateSignedInVisualSpecs, generateVisualSpecs } from "../src/engine/visual/baseline.js";
import type { ScriptRun } from "../src/engine/validation/runner.js";
import type { Step, TestSpec } from "../src/engine/spec/schema.js";
import type { AppModel, PageModel, PageType } from "../src/engine/understanding/app-model.js";
import { bootstrap, type Platform } from "../src/platform/bootstrap.js";
import { buildServer } from "../src/platform/server.js";
import { Worker } from "../src/platform/worker.js";
import { totpAccepted } from "./fixtures/independent-totp.js";

const require = createRequire(import.meta.url);

// ── the app under test ───────────────────────────────────────────────────────
const PORT = 5440;
const BASE = `http://127.0.0.1:${PORT}`;
const ADMIN_TOTP = "JBSWY3DPEHPK3PXP";
const WRONG_TOTP = "GEZDGNBVGY3TQOJQ";
const MEMBER = { username: "member@example.com", password: "pw-member-1" };
const ADMIN = { username: "admin@example.com", password: "pw-admin-1" };
const ACCOUNTS: Record<string, { password: string; role: "member" | "admin" }> = { [MEMBER.username]: { password: MEMBER.password, role: "member" }, [ADMIN.username]: { password: ADMIN.password, role: "admin" } };
const sessions = new Map<string, { role: "member" | "admin"; full: boolean }>();
/** /dashboard answers: served = page delivered to a signed-in browser, bounced = a visitor was sent to /login. */
const dash = { served: 0, bounced: 0 };
let variant = "a";

const shell = (title: string, body: string, nav: string, style = "") => `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${title}</title></head><body style="margin:0;font:20px sans-serif${style}"><nav style="padding:12px;background:#eef">${nav}</nav><main style="padding:16px"><h1>${title}</h1>${body}</main></body></html>`;
const publicNav = '<a href="/">Home</a> <a href="/pricing">Pricing</a> <a href="/login">Log in</a>';
const memberNav = '<a href="/">Home</a> <a href="/pricing">Pricing</a> <a href="/dashboard">Dashboard</a> <a href="/account">Account</a> <form method="post" action="/logout" style="display:inline"><button>Log out</button></form>';
const adminNav = '<a href="/">Home</a> <a href="/pricing">Pricing</a> <a href="/dashboard">Dashboard</a> <a href="/account">Account</a> <a href="/reports">Reports</a> <form method="post" action="/logout" style="display:inline"><button>Log out</button></form>';

const readForm = (req: http.IncomingMessage) =>
    new Promise<URLSearchParams>((resolve) => {
        let raw = "";
        req.on("data", (c) => (raw += c));
        req.on("end", () => resolve(new URLSearchParams(raw)));
    });

const app = http.createServer(async (req, res) => {
    const p = (req.url ?? "/").split("?")[0]!;
    const sid = /sid=([a-f0-9]+)/.exec(req.headers.cookie ?? "")?.[1] ?? "";
    const me = sessions.get(sid);
    const signedIn = me?.full ? me : undefined;
    const nav = signedIn ? (signedIn.role === "admin" ? adminNav : memberNav) : publicNav;
    const html = (status: number, content: string, headers: Record<string, string> = {}, delay = 0) =>
        setTimeout(() => {
            res.writeHead(status, { "content-type": "text/html", ...headers });
            res.end(content);
        }, delay);
    const redirect = (to: string, headers: Record<string, string> = {}) => (res.writeHead(302, { location: to, ...headers }), res.end());

    if (req.method === "POST" && p === "/login") {
        const f = await readForm(req);
        const acct = ACCOUNTS[f.get("email") ?? ""];
        if (!acct || acct.password !== f.get("password")) return html(401, shell("Sign in", '<p role="alert">Invalid email or password</p><form method="post" action="/login"><label>Email <input name="email" type="email"></label> <label>Password <input name="password" type="password"></label> <button type="submit">Log in</button></form>', publicNav));
        const id = crypto.randomBytes(8).toString("hex");
        sessions.set(id, { role: acct.role, full: acct.role !== "admin" }); // the admin also needs the one-time code
        return redirect(acct.role === "admin" ? "/verify" : "/account", { "set-cookie": `sid=${id}; Path=/; HttpOnly` });
    }
    if (p === "/verify") {
        if (!me) return redirect("/login");
        const form = '<form method="post" action="/verify"><label>Code <input name="code" autocomplete="one-time-code"></label> <button type="submit">Verify</button></form>';
        if (req.method === "POST") {
            const f = await readForm(req);
            if (!totpAccepted(ADMIN_TOTP, (f.get("code") ?? "").trim())) return html(401, shell("Two-step verification", `<p role="alert">That code is not valid</p>${form}`, publicNav));
            me.full = true;
            return redirect("/account");
        }
        return html(200, shell("Two-step verification", form, publicNav));
    }
    if (req.method === "POST" && p === "/logout") return redirect("/", { "set-cookie": "sid=; Path=/; Max-Age=0" });

    if (p === "/") return html(200, shell("Acme", "<p>Welcome to Acme.</p>", nav));
    if (p === "/pricing") return html(200, shell("Pricing", "<p>Simple plans.</p>", nav));
    if (p === "/login") return html(200, shell("Sign in", '<form method="post" action="/login"><label>Email <input name="email" type="email"></label> <label>Password <input name="password" type="password"></label> <button type="submit">Log in</button></form>', publicNav));
    // Signed-in only; a visitor is sent to the sign-in page. The dashboard is slow on the server.
    if (p === "/dashboard") {
        if (!signedIn) return dash.bounced++, redirect("/login?next=/dashboard");
        dash.served++;
        const bg = variant === "a" ? "#1f2937" : "#b91c1c";
        return html(200, shell("Dashboard", '<p>Your numbers are up to date.</p><p style="padding:24px">Nothing else to see.</p>', nav, `;background:${bg};color:#fff`), {}, 1000);
    }
    if (p === "/account") return signedIn ? html(200, shell("Your account", "<p>Details.</p>", nav)) : redirect("/login?next=/account");
    if (p === "/ticker") return signedIn ? html(200, shell("Live ticker", `<p>${Date.now()}${Math.random()}</p>`, nav)) : redirect("/login");
    if (p === "/reports") return !signedIn ? redirect("/login?next=/reports") : signedIn.role === "admin" ? html(200, shell("Quarterly reports", "<p>Revenue.</p>", nav)) : html(403, shell("Forbidden", "<p>Access denied.</p>", nav));
    html(404, shell("Not found", "", nav));
});

// ── helpers ──────────────────────────────────────────────────────────────────
const pm = (p: string, title: string, type: PageType, depth = 1): PageModel => ({ url: BASE + p, path: p, title, type, depth, status: 200, headings: [title], forms: [], components: [], links: [], aria: "", text: "", apiCalls: [], revealed: [], consoleErrors: [] });
const model = (loggedIn: boolean): AppModel => ({
    url: BASE + "/",
    origin: BASE,
    siteType: "unknown",
    purpose: "",
    features: [],
    pages: [pm("/", "Acme", "home", 0), pm("/pricing", "Pricing", "content"), pm("/dashboard", "Dashboard", "dashboard"), pm("/account", "Your account", "account"), pm("/reports", "Quarterly reports", "content")],
    navigation: [],
    apis: [],
    authentication: { required: true, loginPath: "/login", mechanisms: ["form"], loggedIn },
    journeys: [],
    externalDependencies: [],
    documentedTestCases: [],
    stats: { pagesVisited: 5, pagesSkipped: 0, apisFound: 0, durationMs: 0 },
});
const ctx = { emit: () => undefined } as unknown as EngineContext;

const run = (over: Partial<ScriptRun> & { steps: ScriptRun["steps"] }): ScriptRun => ({ testId: "WEB-001", status: "failed", durationMs: 1, failedStepIndex: -1, artifacts: [], responses: [], ...over });

// ── pure rules ───────────────────────────────────────────────────────────────
describe("sign-in steps and rules", () => {
    const form: LoginForm = loginFormFrom({ pw: { id: "p", name: "password" }, user: { id: "u", name: "email" }, inForm: true, submitName: "Log in" }, "/login");

    it("reads the form's fields by name, then by a stable id, and falls back to a generic selector", () => {
        expect(form).toMatchObject({ path: "/login", userCss: 'input[name="email"]:visible', passwordCss: 'input[name="password"]:visible' });
        const byId = loginFormFrom({ pw: { id: "pw", name: "" }, user: { id: "login-user", name: "" }, inForm: true, submitName: null }, "/signin");
        expect(byId).toMatchObject({ userCss: 'input[id="login-user"]:visible', passwordCss: 'input[id="pw"]:visible' });
        const generated = loginFormFrom({ pw: { id: ":r1:", name: "" }, user: { id: "field-123456", name: "" }, inForm: false, submitName: "Sign in" }, "/x");
        expect(generated.passwordCss).toBe("input[type=password]:visible");
        expect(generated.userCss).toContain("input[type=email]");
        expect(generated.submit).toEqual({ buttonName: "Sign in" });
        expect(loginFormFrom({ pw: { id: "", name: "" }, user: null, inForm: false, submitName: null }, "/x").submit).toBeUndefined();
    });

    it("builds plain steps that name the account's variables and never carry a secret", () => {
        const steps = signInSteps(defaultAccount(false), form);
        expect(steps.map((s) => s.action)).toEqual(["navigate", "fill", "fill", "click", "assert"]);
        expect(steps[1]).toMatchObject({ value: "{{credentials.username}}" });
        expect(steps[2]).toMatchObject({ value: "{{credentials.password}}" });
        expect(steps[4]).toMatchObject({ check: "hidden", description: "Signed in as the default account: no sign-in form is shown" });

        const admin = signInSteps(roleAccount("admin", true), form);
        expect(admin.map((s) => s.action)).toEqual(["navigate", "fill", "fill", "click", "assert", "fill", "press", "assert"]);
        expect(admin[1]).toMatchObject({ value: "{{credentials.admin.username}}" });
        expect(admin[5]).toMatchObject({ value: "{{credentials.admin.totp}}" });
        expect(JSON.stringify(admin)).not.toMatch(/pw-|JBSWY/);

        const noButton = signInSteps(defaultAccount(false), { ...form, submit: undefined });
        expect(noButton[3]).toMatchObject({ action: "press", key: "Enter" });
        expect(signedInPageSteps(defaultAccount(false), form, "/dashboard", [{ action: "assert", check: "pageSpeed", description: "" }]).slice(-2)).toMatchObject([{ action: "navigate", url: "/dashboard" }, { action: "assert", check: "pageSpeed" }]);
    });

    it("tells a page that needs a sign-in from a public one", () => {
        const view = (over: Partial<Parameters<typeof needsSignIn>[2]>) => ({ status: 200, finalPath: "/p", hasPasswordField: false, text: "hello", ...over });
        expect(needsSignIn("/p", "/login", view({}))).toBe(false);
        expect(needsSignIn("/p", "/login", view({ finalPath: "/login", hasPasswordField: true }))).toBe(true);
        expect(needsSignIn("/p", "/login", view({ finalPath: "/p", hasPasswordField: true }))).toBe(true); // sign-in form shown in place
        expect(needsSignIn("/p", "/login", view({ status: 403 }))).toBe(true);
        expect(needsSignIn("/p", "/login", view({ text: "Access denied" }))).toBe(true);
        expect(needsSignIn("/p", "/login", view({ finalPath: "/other" }))).toBe(false); // an ordinary redirect
        expect(needsSignIn("/login", "/login", view({ finalPath: "/login", hasPasswordField: true }))).toBe(false);
        expect(needsSignIn("/p", "/login", view({ status: 500 }))).toBe(false); // could not tell
        expect(needsSignIn("/p", "/login", view({ status: 0 }))).toBe(false);
    });

    it("explains a sign-in that did not work, and ignores failures after the sign-in", () => {
        const spec = { steps: signedInPageSteps(roleAccount("admin", true), form, "/reports", [{ action: "assert", check: "pageSpeed", description: "" }]) } as TestSpec;
        const failedAt = (index: number, error = "boom") => run({ steps: [{ index, title: `${index + 1}. step`, status: "failed", error }] });
        expect(signInFailure(spec, failedAt(4))).toBe("Could not sign in as admin: the sign-in form was still shown after the sign-in details were submitted. Check the account's username and password (and whether the app asks for anything more).");
        expect(signInFailure(spec, failedAt(7))).toBe("Could not sign in as admin: the one-time code was not accepted. Check the authenticator secret and this computer's clock.");
        expect(signInFailure(spec, failedAt(1, "locator.fill: Timeout 30000ms exceeded.\nCall log: ..."))).toBe('Could not sign in as admin: the step "2. step" did not work (locator.fill: Timeout 30000ms exceeded.).');
        expect(signInFailure(spec, failedAt(9, "Page speed check failed: ..."))).toBeUndefined(); // the page under test was reached: not a sign-in problem
        expect(signInFailure(spec, run({ status: "passed", steps: [] }))).toBeUndefined();
        expect(signInFailure({ steps: [{ action: "navigate", url: "/", description: "" }] } as TestSpec, failedAt(0))).toBeUndefined(); // not a signed-in spec
    });

    it("adds the session token to the budgets", () => {
        expect(signedInBudgets(undefined)).toBe("signed-in");
        expect(signedInBudgets("lcp:3000 slow-4g")).toBe("lcp:3000 slow-4g signed-in");
    });
});

// ── real browser ─────────────────────────────────────────────────────────────
describe("signed-in speed and visual checks on a real app", () => {
    let platform: Platform;
    let worker: Worker;
    let server: Awaited<ReturnType<typeof buildServer>>;
    let dir: string;
    let browser: Browser;
    let plan: SignedInPlan;

    beforeAll(async () => {
        await new Promise<void>((r) => app.listen(PORT, "127.0.0.1", r));
        for (const k of ["ANTHROPIC_API_KEY", "OPENAI_API_KEY", "GOOGLE_GENERATIVE_AI_API_KEY", "LLM_API_KEY"]) process.env[k] = "";
        dir = fs.mkdtempSync(path.join(os.tmpdir(), "aitp-signed-in-"));
        platform = bootstrap(loadConfig({ DATA_DIR: dir, LLM_PROVIDER: "anthropic" }));
        server = await buildServer(platform);
        worker = new Worker(platform, 200);
        worker.start();
        browser = await launchChromium(true);
    }, 60_000);
    afterAll(async () => {
        await browser?.close().catch(() => undefined);
        await worker?.stop();
        await server?.close();
        platform?.db.close();
        await new Promise((r) => app.close(r));
        fs.rmSync(dir, { recursive: true, force: true });
    });

    const call = async (method: "GET" | "POST" | "PUT", url: string, payload?: unknown) => {
        const res = await server.inject({ method, url, payload: payload as never });
        return { status: res.statusCode, body: res.body ? JSON.parse(res.body) : null };
    };
    async function waitForJob(jobId: string) {
        for (let i = 0; i < 900; i++) {
            const j = (await call("GET", `/api/test-generation/${jobId}`)).body;
            if (["COMPLETED", "PARTIALLY_COMPLETED", "FAILED"].includes(j.status)) return j;
            await new Promise((r) => setTimeout(r, 500));
        }
        throw new Error("job did not finish");
    }
    type T = { id: string; title: string; validationStatus: string; validationReason: string | null; severity: { severity: string } | null };
    const testsOf = async (projectId: string) => Object.fromEntries(((await call("GET", `/api/projects/${projectId}/tests`)).body as T[]).map((t) => [t.title, t])) as Record<string, T>;
    const newProject = async (name: string, roles: unknown[] = []) => {
        const id = (await call("POST", "/api/projects", { name })).body.id as string;
        if (roles.length) expect((await call("PUT", `/api/projects/${id}/roles`, { roles })).status).toBe(200);
        return id;
    };
    const importSpecs = async (projectId: string, specs: unknown[], credentials: { username: string; password: string } | undefined = MEMBER) => {
        const res = await call("POST", `/api/projects/${projectId}/specs`, { specs, baseUrl: BASE, ...(credentials ? { credentials } : {}) });
        expect(res.status, JSON.stringify(res.body)).toBe(202);
        await waitForJob(res.body.jobId);
    };
    const roles = [
        { name: "admin", username: ADMIN.username, password: ADMIN.password, totpSecret: ADMIN_TOTP },
        { name: "badcode", username: ADMIN.username, password: ADMIN.password, totpSecret: WRONG_TOTP },
    ];
    const reach: Reach[] = [
        { who: "anonymous", pages: [{ path: "/", heading: "Acme" }, { path: "/pricing", heading: "Pricing" }] },
        { who: "admin", needsCode: true, pages: [{ path: "/", heading: "Acme" }, { path: "/dashboard", heading: "Dashboard" }, { path: "/account", heading: "Your account" }, { path: "/reports", heading: "Quarterly reports" }] },
    ];
    const pick = <S extends { title: string }>(specs: S[], needle: string): S[] => specs.filter((s) => s.title.includes(needle));

    it("plans signed-in pages by looking: only pages a visitor cannot open, for each account, and leaves public pages to the anonymous checks", async () => {
        const before = { ...dash };
        plan = (await planSignedIn(ctx, browser, { model: model(true), defaultAccount: defaultAccount(false), roles: roles.map((r) => ({ name: r.name, username: r.username, password: r.password, totpSecret: r.totpSecret })), reach }))!;
        expect(plan).toBeTruthy();
        expect(plan.form).toMatchObject({ path: "/login", userCss: 'input[name="email"]:visible', passwordCss: 'input[name="password"]:visible' });
        expect([...plan.gated].sort()).toEqual(["/account", "/dashboard", "/reports"]);
        expect(plan.accounts.map((a) => a.account.who)).toEqual(["the default account", "admin"]);
        expect(plan.accounts[0]!.pages.map((p) => p.path)).toEqual(["/account", "/dashboard", "/reports"]); // at most 3, in the planner's order of importance
        expect(plan.accounts[0]!.pages[1]).toMatchObject({ label: "Dashboard", priority: "medium" });
        expect(plan.accounts[1]!.account.needsCode).toBe(true);
        expect(plan.accounts[1]!.pages.map((p) => p.path).sort()).toEqual(["/account", "/dashboard", "/reports"]);
        // the survey only asked as a visitor: nothing was served to a signed-in browser
        expect(dash.served).toBe(before.served);

        // the anonymous families stop short of the gated pages and keep the public ones
        const anon = generatePerformanceSpecs(model(true), { maxPages: 5, excludePaths: plan.gated }).map((s) => s.title);
        expect(anon.join("|")).toMatch(/\(\/\)/);
        expect(anon.join("|")).toMatch(/\(\/pricing\)/);
        expect(anon.join("|")).not.toMatch(/dashboard|account|reports/);
        // without a plan, the old rule (drop account/dashboard pages of a logged-in crawl) is unchanged
        expect(generateVisualSpecs(model(true), { maxPages: 6 }).map((s) => s.title.match(/\((.*)\)$/)![1])).toEqual(["/", "/pricing", "/reports"]);
        expect(generateVisualSpecs(model(true), { maxPages: 6, excludePaths: plan.gated }).map((s) => s.title.match(/\((.*)\)$/)![1])).toEqual(["/", "/pricing"]);
    }, 120_000);

    it("titles each spec with who is signed in and keeps the category, origin and no secret", () => {
        const perf = generateSignedInPerformanceSpecs(plan, { budgets: "ttfb:500" });
        const visual = generateSignedInVisualSpecs(plan);
        expect(perf).toHaveLength(6);
        expect(visual).toHaveLength(6);
        expect(perf.find((p) => p.title.includes("(/dashboard) (signed in as the default"))).toMatchObject({ title: "Dashboard page loads quickly (/dashboard) (signed in as the default account)", category: "Performance", type: "performance", source: { origin: "performance-check" } });
        expect(visual.map((v) => v.title)).toContain("Content page looks the same as its approved baseline (/reports) (signed in as admin)");
        expect(visual[0]).toMatchObject({ category: "Visual", type: "visual", source: { origin: "visual-baseline" } });
        const speedStep = perf[0]!.steps.at(-1) as Extract<Step, { action: "assert" }>;
        expect(speedStep).toMatchObject({ check: "pageSpeed", expected: "ttfb:500 signed-in" });
        expect(JSON.stringify([perf, visual])).not.toMatch(/pw-member|pw-admin|JBSWY|member@example|admin@example/);
    });

    let speed: Record<string, T> = {};
    let speedServed = 0;
    let speedBounced = 0;
    let scriptText = "";
    it("measures the dashboard (not the sign-in page) as the signed-in account and flags its slow server against a budget", async () => {
        const project = await newProject("Signed-in speed", roles);
        const specs = generateSignedInPerformanceSpecs(plan, { budgets: "ttfb:500" });
        const before = { ...dash };
        await importSpecs(project, [...pick(specs, "(/dashboard) (signed in as the default account)"), ...pick(specs, "(/account) (signed in as the default account)"), ...pick(specs, "(/reports) (signed in as admin)")]);
        speed = await testsOf(project);
        speedServed = dash.served - before.served;
        speedBounced = dash.bounced - before.bounced;

        const slow = speed["Dashboard page loads quickly (/dashboard) (signed in as the default account)"]!;
        expect(slow.validationStatus, slow.validationReason ?? "").toBe("NEEDS_REVIEW");
        expect(slow.validationReason).toContain("Page speed check failed:");
        expect(slow.validationReason).toMatch(/The server takes 1\.\d s to start responding \(aim for under 500 ms\)/);
        expect(["medium", "high"]).toContain(slow.severity!.severity);

        // fast signed-in pages pass: the sign-in worked and the session was carried into the measurement contexts
        const account = speed["Account page loads quickly (/account) (signed in as the default account)"]!;
        expect(account.validationStatus, account.validationReason ?? "").toBe("VALIDATED");
        // the admin signs in with an authenticator code and reaches a page a member may not open
        const reports = speed["Content page loads quickly (/reports) (signed in as admin)"]!;
        expect(reports.validationStatus, reports.validationReason ?? "").toBe("VALIDATED");
        scriptText = (await call("GET", `/api/tests/${slow.id}`)).body.scripts[0].content as string;
    }, 300_000);

    it("carried the session into every fresh load: 1 load by the test + 3 measurements, none turned away", () => {
        expect(speedServed).toBe(4);
        expect(speedBounced).toBe(0);
    });

    it("records the dashboard's own timings as history", async () => {
        const slow = speed["Dashboard page loads quickly (/dashboard) (signed in as the default account)"]!;
        const perf = (await call("GET", `/api/tests/${slow.id}/performance`)).body;
        const ttfb = perf.latest.find((m: { metric: string }) => m.metric === "ttfb");
        expect(ttfb.value).toBeGreaterThan(800); // the 1 s server delay: the sign-in page would be near 0
        expect(ttfb.budget).toBe(500);
    });

    it("without the session token a fresh context is a visitor, so it would silently measure the sign-in page (why the token exists)", async () => {
        const project = await newProject("No token");
        const steps: Step[] = signedInPageSteps(defaultAccount(false), plan.form, "/dashboard", [{ action: "assert", check: "pageSpeed", expected: "ttfb:500", description: "" }]);
        const before = { ...dash };
        await importSpecs(project, [{ title: "Dashboard without token", kind: "web", category: "Performance", type: "performance", priority: "high", source: { origin: "performance-check" }, steps }]);
        const t = (await testsOf(project))["Dashboard without token"]!;
        expect(t.validationStatus).toBe("VALIDATED"); // the sign-in page is fast
        expect(dash.bounced - before.bounced).toBe(3);
        expect(dash.served - before.served).toBe(1);
    }, 120_000);

    it("a wrong password is a plain failed validation that says it could not sign in, never a finding", async () => {
        const project = await newProject("Wrong password");
        const specs = [...pick(generateSignedInPerformanceSpecs(plan, { budgets: "ttfb:500" }), "(/dashboard) (signed in as the default account)"), ...pick(generateSignedInVisualSpecs(plan), "(/account) (signed in as the default account)")];
        await importSpecs(project, specs, { username: MEMBER.username, password: "not-the-password" });
        const tests = Object.values(await testsOf(project));
        expect(tests).toHaveLength(2);
        for (const t of tests) {
            expect(t.validationStatus).toBe("FAILED_VALIDATION");
            expect(t.validationReason).toMatch(/^Could not sign in as the default account: the sign-in form was still shown/);
            expect(t.validationReason).not.toContain("Page speed check failed");
            expect(t.severity).toBeNull();
        }
    }, 180_000);

    it("a wrong authenticator secret says the code was not accepted", async () => {
        const project = await newProject("Wrong code", roles);
        const steps = signedInPageSteps(roleAccount("badcode", true), plan.form, "/reports", [{ action: "assert", check: "pageSpeed", expected: "signed-in", description: "" }]);
        await importSpecs(project, [{ title: "Reports with a bad code", kind: "web", category: "Performance", type: "performance", priority: "high", source: { origin: "performance-check" }, steps }], undefined);
        const t = (await testsOf(project))["Reports with a bad code"]!;
        expect(t.validationStatus).toBe("FAILED_VALIDATION");
        expect(t.validationReason).toBe("Could not sign in as badcode: the one-time code was not accepted. Check the authenticator secret and this computer's clock.");
    }, 120_000);

    it("captures a stable baseline for a signed-in page, refuses an unstable one, and reports a visual change", async () => {
        const project = await newProject("Signed-in visual");
        const visual = generateSignedInVisualSpecs(plan);
        const dashboard = pick(visual, "(/dashboard) (signed in as the default account)");
        const ticker: Step[] = signedInPageSteps(defaultAccount(false), plan.form, "/ticker", [{ action: "assert", check: "screenshot", expected: 100, description: "" }]);
        await importSpecs(project, [...dashboard, { title: "Ticker baseline", kind: "web", category: "Visual", type: "visual", priority: "low", source: { origin: "visual-baseline" }, steps: ticker }]);
        const tests = await testsOf(project);
        const home = tests[dashboard[0]!.title]!;
        expect(home.validationStatus, home.validationReason ?? "").toBe("VALIDATED");
        const detail = (await call("GET", `/api/tests/${home.id}`)).body;
        expect(detail.executions).toHaveLength(2); // capture + stability re-run
        const stepCount = dashboard[0]!.steps!.length;
        const baselines = platform.repo.listArtifacts({ testId: home.id }).filter((a) => a.kind === "baseline");
        expect(baselines.map((a) => path.posix.basename(a.path))).toEqual([expect.stringMatching(new RegExp(`^WEB-\\d+-${stepCount}\\.png$`))]);

        const unstable = tests["Ticker baseline"]!;
        expect(unstable.validationStatus).toBe("FAILED_VALIDATION");
        expect(unstable.validationReason).toMatch(/not visually stable/);
        expect(unstable.severity).toBeNull();

        variant = "b";
        await waitForJob((await call("POST", `/api/tests/${home.id}/validate`)).body.jobId);
        variant = "a";
        const changed = (await call("GET", `/api/tests/${home.id}`)).body;
        expect(changed.validationStatus).toBe("NEEDS_REVIEW");
        expect(changed.validationReason).toMatch(/^Visual change: \d+ pixels differ/);
    }, 300_000);

    it("keeps the script portable: environment variable names only, and it passes under plain Playwright", async () => {
        expect(scriptText).toContain("async function pageSpeedAssert");
        expect(scriptText).toContain("storageState()");
        expect(scriptText).toContain("process.env.TEST_USERNAME");
        expect(scriptText).toContain("process.env.TEST_PASSWORD");
        expect(scriptText).toContain('"ttfb:500 signed-in"');
        expect(scriptText).not.toMatch(/pw-member|member@example|pw-admin|JBSWY/);
        const adminDetail = (await call("GET", `/api/tests/${speed["Content page loads quickly (/reports) (signed in as admin)"]!.id}`)).body;
        const adminScript = adminDetail.scripts[0].content as string;
        expect(adminScript).toContain("function totpCode(");
        expect(adminScript).toContain("process.env.TEST_ADMIN_TOTP_SECRET");
        expect(adminScript).not.toMatch(/pw-admin|admin@example|JBSWY/);

        // Run the member's script exactly as a user would: plain Playwright, a config, the credentials only in the environment.
        const work = path.join(process.cwd(), ".scratch", `signed-in-plain-${crypto.randomBytes(4).toString("hex")}`);
        fs.mkdirSync(work, { recursive: true });
        try {
            // A budget this page passes: the point is that the sign-in and the carried session work, not the timing.
            fs.writeFileSync(path.join(work, "script.spec.ts"), scriptText.replace('"ttfb:500 signed-in"', '"ttfb:5000 signed-in"'));
            fs.writeFileSync(path.join(work, "playwright.config.ts"), 'import { defineConfig } from "@playwright/test";\nexport default defineConfig({ testDir: ".", testMatch: /.*\\.spec\\.ts$/, timeout: 90_000, reporter: "line" });\n');
            const env: NodeJS.ProcessEnv = { PATH: process.env.PATH, SystemRoot: process.env.SystemRoot, USERPROFILE: process.env.USERPROFILE, LOCALAPPDATA: process.env.LOCALAPPDATA, APPDATA: process.env.APPDATA, TEMP: process.env.TEMP, TMP: process.env.TMP, HOME: process.env.HOME, BASE_URL: BASE, TEST_USERNAME: MEMBER.username, TEST_PASSWORD: MEMBER.password };
            const out = await new Promise<{ code: number | null; text: string }>((resolve) => {
                const child = spawn(process.execPath, [require.resolve("@playwright/test/cli"), "test", "--config", "playwright.config.ts", "--workers=1"], { cwd: work, env, stdio: ["ignore", "pipe", "pipe"] });
                let text = "";
                child.stdout.on("data", (d) => (text += d));
                child.stderr.on("data", (d) => (text += d));
                child.on("close", (code) => resolve({ code, text }));
            });
            expect(out.code, out.text).toBe(0);
            expect(out.text).toMatch(/1 passed/);
        } finally {
            fs.rmSync(work, { recursive: true, force: true });
        }
    }, 180_000);

    it("the full analysis adds signed-in speed and visual checks next to the anonymous ones, without duplicating pages", async () => {
        const project = await newProject("Whole analysis", [{ name: "admin", username: ADMIN.username, password: ADMIN.password, totpSecret: ADMIN_TOTP }]);
        const queued = await call("POST", `/api/projects/${project}/test-generation`, {
            url: BASE,
            credentials: MEMBER,
            targets: ["web"],
            healthChecks: false,
            securityChecks: false,
            inputChecks: false,
            accessibility: false,
            performanceChecks: true,
            performanceBudgets: "ttfb:700",
            visual: true,
            maxPages: 12,
        });
        expect(queued.status).toBe(202);
        await waitForJob(queued.body.jobId);
        const tests = Object.values(await testsOf(project)).filter((t) => /loads quickly|looks the same/.test(t.title));
        const titles = tests.map((t) => t.title);

        for (const fam of ["loads quickly", "looks the same as its approved baseline"]) {
            const f = titles.filter((t) => t.includes(fam));
            // public pages stay anonymous; pages behind the login appear once per account, saying who is signed in
            expect(f.filter((t) => /\(\/(pricing)?\)$/.test(t)), f.join("\n")).toHaveLength(2);
            expect(f.some((t) => t.includes("(/dashboard) (signed in as the default account)")), f.join("\n")).toBe(true);
            expect(f.some((t) => t.includes("(/dashboard) (signed in as admin)")), f.join("\n")).toBe(true);
            expect(f.some((t) => t.includes("(/reports) (signed in as admin)")), f.join("\n")).toBe(true);
            expect(f.filter((t) => /\(\/(dashboard|account|reports)\)$/.test(t)), "a gated page must not also be tested anonymously").toEqual([]);
        }
        const slow = tests.find((t) => t.title.includes("(/dashboard) (signed in as the default account)") && t.title.includes("loads quickly"))!;
        expect(slow.validationStatus, slow.validationReason ?? "").toBe("NEEDS_REVIEW");
        expect(slow.validationReason).toMatch(/The server takes/);
        for (const t of tests.filter((x) => x.title.includes("loads quickly") && !x.title.includes("/dashboard"))) expect(t.validationStatus, `${t.title}: ${t.validationReason}`).toBe("VALIDATED");
        for (const t of tests.filter((x) => x.title.includes("looks the same"))) expect(t.validationStatus, `${t.title}: ${t.validationReason}`).toBe("VALIDATED");
    }, 900_000);
});
